/* ==========================================================================
   SIDEBAR DRAWER OVERLAY
   ========================================================================== */

.sidebar-drawer-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(4px);
  z-index: 10000;
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition-normal), visibility var(--transition-normal);
}

.sidebar-drawer-backdrop.open {
  opacity: 1;
  visibility: visible;
}

.sidebar-drawer {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 320px;
  background-color: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  z-index: 10001;
  display: flex;
  flex-direction: column;
  transform: translateX(-100%);
  transition: transform var(--transition-normal);
  padding: 1.25rem 1rem;
}

.sidebar-drawer-backdrop.open .sidebar-drawer {
  transform: translateX(0);
}

.sidebar-drawer-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.25rem;
  padding-bottom: 0.25rem;
}

.sidebar-drawer-logo {
  cursor: pointer;
  display: flex;
  align-items: center;
  color: var(--text-primary);
}

.sidebar-drawer-close-btn {
  background: transparent;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 6px;
  border-radius: 6px;
  transition: background-color var(--transition-fast), color var(--transition-fast);
}

.sidebar-drawer-close-btn:hover {
  background-color: var(--bg-tertiary);
  color: var(--text-primary);
}

.sidebar-drawer-nav {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
}

.sidebar-drawer-nav-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.5rem 0.75rem;
  border-radius: var(--border-radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-primary);
  text-decoration: none !important;
  cursor: pointer;
  transition: background-color var(--transition-fast), color var(--transition-fast);
}

.sidebar-drawer-nav-item:hover {
  background-color: var(--bg-tertiary);
  color: var(--text-primary) !important;
}

.sidebar-drawer-nav-item.active {
  background-color: var(--accent-blue-bg);
  color: var(--accent-blue) !important;
}

.sidebar-drawer-nav-item i {
  width: 16px;
  height: 16px;
  color: var(--text-secondary);
  flex-shrink: 0;
}

.sidebar-drawer-nav-item.active i {
  color: var(--accent-blue);
}

.sidebar-drawer-divider {
  height: 1px;
  background-color: var(--border-color);
  margin: 0.75rem 0.25rem;
}

.sidebar-drawer-repos-section {
  display: flex;
  flex-direction: column;
  flex-grow: 1;
  overflow: hidden;
  padding: 0 0.5rem;
}

.sidebar-drawer-repos-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 0.75rem;
  margin-top: 0.25rem;
}

.sidebar-drawer-repos-search-btn {
  background: transparent;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
  border-radius: 4px;
  transition: background-color var(--transition-fast), color var(--transition-fast);
}

.sidebar-drawer-repos-search-btn:hover {
  background-color: var(--bg-tertiary);
  color: var(--text-primary);
}

.sidebar-drawer-search-container {
  margin-bottom: 0.75rem;
  display: flex;
  align-items: center;
  position: relative;
}

.sidebar-drawer-search-container input {
  width: 100%;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 6px 10px;
  font-size: 0.8125rem;
  color: var(--text-primary);
  outline: none;
  transition: border-color 0.2s;
}

.sidebar-drawer-search-container input:focus {
  border-color: var(--accent-blue);
}

.sidebar-drawer-repo-list {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  overflow-y: auto;
  flex-grow: 1;
  padding-right: 2px;
}

.sidebar-drawer-repo-item {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.4rem 0.5rem;
  border-radius: var(--border-radius-sm);
  font-size: 0.8125rem;
  color: var(--text-primary);
  text-decoration: none !important;
  cursor: pointer;
  transition: background-color var(--transition-fast);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar-drawer-repo-item:hover {
  background-color: var(--bg-tertiary);
}

.sidebar-drawer-repo-avatar {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  object-fit: cover;
  border: 1px solid var(--border-color);
  flex-shrink: 0;
}

.sidebar-drawer-repo-name-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sidebar-drawer-show-more {
  border-top: 1px solid var(--border-color);
  padding-top: 0.75rem;
  margin-top: 0.5rem;
  flex-shrink: 0;
}

