export function renderSidebarDrawer(state, actions) {
  const defaultOwnerAvatar = "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=150&auto=format&fit=crop&q=80";
  const secondOwnerAvatar = "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&auto=format&fit=crop&q=80";

  const isDrawerOpen = state.isSidebarDrawerOpen;

  const repoItems = state.repos.map((repo, idx) => {
    const owner = repo.owner || state.user.username;
    const avatar = owner === "theankittsaini" ? secondOwnerAvatar : defaultOwnerAvatar;
    const repoFullName = `${owner}/${repo.name}`;
    const hideStyle = idx >= 5 ? 'style="display: none;"' : '';

    return `
      <div class="sidebar-drawer-repo-item" ${hideStyle} data-id="${repo.id}" data-name="${repoFullName}">
        <img src="${avatar}" class="sidebar-drawer-repo-avatar" alt="${owner}" />
        <span class="sidebar-drawer-repo-name-text">${repoFullName}</span>
      </div>
    `;
  }).join('');

  return `
    <div class="sidebar-drawer-backdrop ${isDrawerOpen ? 'open' : ''}" id="sidebar-drawer-backdrop">
      <div class="sidebar-drawer">
        <!-- Header -->
        <div class="sidebar-drawer-header">
          <div class="sidebar-drawer-logo" id="drawer-logo-btn">
            <i data-lucide="github" style="width: 24px; height: 24px;"></i>
          </div>
          <button class="sidebar-drawer-close-btn" id="sidebar-drawer-close-btn" title="Close menu">
            <i data-lucide="x" style="width: 18px; height: 18px;"></i>
          </button>
        </div>

        <!-- Navigation Links -->
        <div class="sidebar-drawer-nav">
          <a class="sidebar-drawer-nav-item ${state.activeRepoId === null && state.activeView === 'dashboard' ? 'active' : ''}" id="drawer-nav-home">
            <i data-lucide="home"></i>
            <span>Home</span>
          </a>
          <a class="sidebar-drawer-nav-item ${state.activeRepoId === null && state.activeView === 'issues' ? 'active' : ''}" id="drawer-nav-issues">
            <i data-lucide="circle-dot"></i>
            <span>All issues</span>
          </a>
          <a class="sidebar-drawer-nav-item ${state.activeRepoId === null && state.activeView === 'pulls' ? 'active' : ''}" id="drawer-nav-pulls">
            <i data-lucide="git-pull-request"></i>
            <span>All pull requests</span>
          </a>
          <a class="sidebar-drawer-nav-item" id="drawer-nav-repos">
            <i data-lucide="book-marked"></i>
            <span>All repositories</span>
          </a>
          <a class="sidebar-drawer-nav-item" id="drawer-nav-projects">
            <i data-lucide="table"></i>
            <span>Projects</span>
          </a>
          <a class="sidebar-drawer-nav-item" id="drawer-nav-discussions">
            <i data-lucide="message-square"></i>
            <span>Discussions</span>
          </a>
          <a class="sidebar-drawer-nav-item" id="drawer-nav-codespaces">
            <i data-lucide="terminal"></i>
            <span>Codespaces</span>
          </a>
          <a class="sidebar-drawer-nav-item" id="drawer-nav-copilot">
            <i data-lucide="sparkles"></i>
            <span>Copilot</span>
          </a>
        </div>

        <div class="sidebar-drawer-divider"></div>

        <!-- Secondary Navigation Links -->
        <div class="sidebar-drawer-nav">
          <a class="sidebar-drawer-nav-item" id="drawer-nav-explore">
            <i data-lucide="compass"></i>
            <span>Explore</span>
          </a>
          <a class="sidebar-drawer-nav-item" id="drawer-nav-marketplace">
            <i data-lucide="shopping-bag"></i>
            <span>Marketplace</span>
          </a>
          <a class="sidebar-drawer-nav-item" id="drawer-nav-mcp">
            <i data-lucide="layers"></i>
            <span>MCP registry</span>
          </a>
        </div>

        <div class="sidebar-drawer-divider"></div>

        <!-- Top Repositories section -->
        <div class="sidebar-drawer-repos-section">
          <div class="sidebar-drawer-repos-header">
            <span>Top repositories</span>
            <button class="sidebar-drawer-repos-search-btn" id="drawer-repos-search-btn" title="Search repositories">
              <i data-lucide="search" style="width: 14px; height: 14px;"></i>
            </button>
          </div>

          <div class="sidebar-drawer-search-container" id="drawer-search-container" style="display: none; margin-bottom: 0.75rem;">
            <input 
              type="text" 
              id="drawer-repo-search-input" 
              placeholder="Search repositories..." 
            />
          </div>

          <div class="sidebar-drawer-repo-list" id="drawer-repo-list">
            ${repoItems || '<div style="font-size: 0.75rem; color: var(--text-muted); padding: 0.5rem;">No repositories found.</div>'}
          </div>

          <div class="sidebar-drawer-show-more" id="drawer-show-more-wrapper" style="${state.repos.length <= 5 ? 'display: none;' : ''}">
            <button class="btn btn-sm" id="drawer-show-more-btn" style="background: transparent; border: none; color: var(--text-secondary); cursor: pointer; font-size: 0.75rem; display: flex; align-items: center; gap: 0.25rem; padding: 0;">
              Show more
            </button>
          </div>
        </div>
      </div>
    </div>
  `;
}

export function attachSidebarDrawerListeners(state, actions) {
  const backdrop = document.getElementById("sidebar-drawer-backdrop");
  const closeBtn = document.getElementById("sidebar-drawer-close-btn");
  const searchBtn = document.getElementById("drawer-repos-search-btn");
  const searchContainer = document.getElementById("drawer-search-container");
  const searchInput = document.getElementById("drawer-repo-search-input");
  const showMoreBtn = document.getElementById("drawer-show-more-btn");
  const logoBtn = document.getElementById("drawer-logo-btn");

  const closeDrawer = () => {
    actions.toggleSidebarDrawer(false);
  };

  // Close actions
  if (backdrop) {
    backdrop.addEventListener("click", (e) => {
      if (e.target === backdrop) {
        closeDrawer();
      }
    });
  }
  if (closeBtn) closeBtn.addEventListener("click", closeDrawer);
  if (logoBtn) {
    logoBtn.addEventListener("click", () => {
      closeDrawer();
      actions.navigateToDashboard();
    });
  }

  // Home Navigation
  const homeBtn = document.getElementById("drawer-nav-home");
  if (homeBtn) {
    homeBtn.addEventListener("click", () => {
      closeDrawer();
      actions.navigateToDashboard();
    });
  }

  // All issues Navigation
  const issuesBtn = document.getElementById("drawer-nav-issues");
  if (issuesBtn) {
    issuesBtn.addEventListener("click", () => {
      closeDrawer();
      actions.navigateToGlobalIssues();
    });
  }

  // All pull requests Navigation
  const pullsBtn = document.getElementById("drawer-nav-pulls");
  if (pullsBtn) {
    pullsBtn.addEventListener("click", () => {
      closeDrawer();
      actions.navigateToGlobalPulls();
    });
  }

  // All repositories Navigation
  const reposBtn = document.getElementById("drawer-nav-repos");
  if (reposBtn) {
    reposBtn.addEventListener("click", () => {
      closeDrawer();
      actions.navigateToProfile();
      setTimeout(() => {
        const reposTab = document.getElementById("profile-repos-tab-link");
        if (reposTab) reposTab.click();
      }, 50);
    });
  }

  // Placeholders for other pages
  const placeholderIds = [
    "drawer-nav-projects",
    "drawer-nav-discussions",
    "drawer-nav-codespaces",
    "drawer-nav-copilot",
    "drawer-nav-explore",
    "drawer-nav-marketplace",
    "drawer-nav-mcp"
  ];
  placeholderIds.forEach(id => {
    const btn = document.getElementById(id);
    if (btn) {
      btn.addEventListener("click", () => {
        closeDrawer();
        const text = btn.querySelector("span").textContent;
        actions.navigateToPlaceholderModule(text);
      });
    }
  });

  // Repo search toggle
  if (searchBtn && searchContainer && searchInput) {
    searchBtn.addEventListener("click", () => {
      const isHidden = searchContainer.style.display === "none";
      if (isHidden) {
        searchContainer.style.display = "flex";
        searchInput.focus();
      } else {
        searchContainer.style.display = "none";
        searchInput.value = "";
        resetRepoFilter();
      }
    });
  }

  // Repo filtering
  const repoItems = document.querySelectorAll(".sidebar-drawer-repo-item");
  const showMoreWrapper = document.getElementById("drawer-show-more-wrapper");
  let isExpanded = false;

  const resetRepoFilter = () => {
    repoItems.forEach((item, idx) => {
      if (idx >= 5 && !isExpanded) {
        item.style.display = "none";
      } else {
        item.style.display = "flex";
      }
    });
    if (showMoreWrapper) {
      showMoreWrapper.style.display = state.repos.length <= 5 ? "none" : "block";
    }
  };

  if (searchInput) {
    searchInput.addEventListener("input", (e) => {
      const query = e.target.value.toLowerCase().trim();
      if (!query) {
        resetRepoFilter();
        return;
      }

      if (showMoreWrapper) showMoreWrapper.style.display = "none";

      repoItems.forEach(item => {
        const name = item.getAttribute("data-name").toLowerCase();
        if (name.includes(query)) {
          item.style.display = "flex";
        } else {
          item.style.display = "none";
        }
      });
    });
  }

  // Show more button
  if (showMoreBtn) {
    showMoreBtn.addEventListener("click", () => {
      isExpanded = !isExpanded;
      if (isExpanded) {
        showMoreBtn.textContent = "Show less";
        repoItems.forEach(item => {
          item.style.display = "flex";
        });
      } else {
        showMoreBtn.textContent = "Show more";
        repoItems.forEach((item, idx) => {
          if (idx >= 5) {
            item.style.display = "none";
          } else {
            item.style.display = "flex";
          }
        });
      }
    });
  }

  // Repository Detail Redirect
  repoItems.forEach(item => {
    item.addEventListener("click", () => {
      const repoId = item.getAttribute("data-id");
      closeDrawer();
      actions.navigateToRepo(repoId);
    });
  });
}

