}

function renderGlobalIssues(state, actions) {
  // Aggregate all issues
  const allIssues = [];
  state.repos.forEach(repo => {
    repo.issues.forEach(issue => {
      allIssues.push({
        ...issue,
        repoId: repo.id,
        repoName: `${repo.owner || state.user.username}/${repo.name}`
      });
    });
  });

  // Sort by date descending
  allIssues.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

  const issueRows = allIssues.map(issue => {
    const formattedDate = new Date(issue.createdAt).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric'
    });

    let labelTag = '';
    if (issue.title.toLowerCase().includes('bug')) {
      labelTag = `<span class="label-badge label-bug">Bug</span>`;
    } else if (issue.title.toLowerCase().includes('test') || issue.title.toLowerCase().includes('doc')) {
      labelTag = `<span class="label-badge label-documentation">Documentation</span>`;
    } else {
      labelTag = `<span class="label-badge label-feature">Feature</span>`;
    }

    return `
      <div class="issue-row global-issue-item" data-repo-id="${issue.repoId}" data-issue-id="${issue.id}" style="cursor: pointer;">
        <div class="issue-icon ${issue.status}">
          <i data-lucide="circle-dot" style="width: 16px; height: 16px;"></i>
        </div>

        <div class="issue-main">
          <div class="issue-title-line">
            <span class="issue-title" style="font-weight: 600; color: var(--text-primary);">${issue.title}</span>
            <span class="issue-labels">${labelTag}</span>
            <span style="font-size: 0.75rem; color: var(--accent-blue); margin-left: 0.5rem;">${issue.repoName}</span>
          </div>
          <div class="issue-subinfo">
            #${issue.id} opened on ${formattedDate} by ${issue.author}
          </div>
        </div>

        <div class="issue-row-aside">
          ${issue.comments.length ? `
            <i data-lucide="message-square" style="width: 14px; height: 14px;"></i>
            <span>${issue.comments.length}</span>
          ` : ''}
        </div>
      </div>
    `;
  }).join('');

  return `
    <div class="content-wrapper" style="padding: 1.5rem 1rem; max-width: 1200px; margin: 0 auto;">
      <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 1.5rem;">
        <div style="font-weight: 700; font-size: 1.25rem; display: flex; align-items: center; gap: 0.5rem; color: var(--text-primary);">
          <i data-lucide="circle-dot" style="color: var(--accent-green);"></i>
          <span>Global Issues Tracker</span>
        </div>
      </div>

      <div class="panel-container">
        <div class="panel-header" style="background: var(--bg-secondary); border-bottom: 1px solid var(--border-color); padding: 0.75rem 1rem;">
          <span style="font-size: 0.8125rem; font-weight: 600; color: var(--text-secondary);">
            ${allIssues.length} Total Issues across all repositories
          </span>
        </div>

        <div class="issue-list">
          ${issueRows || `
            <div class="empty-view-placeholder" style="padding: 4rem 2rem; text-align: center;">
              <i data-lucide="circle-check-big" style="width: 48px; height: 48px; color: var(--text-muted); margin-bottom: 1rem;"></i>
              <h3>No issues found</h3>
              <p style="color: var(--text-secondary); font-size: 0.875rem;">Create a repository or issue to see them aggregated here!</p>
            </div>
          `}
        </div>
      </div>
    </div>
  `;
}

function renderGlobalPulls(state, actions) {
  // Aggregate all pull requests
  const allPulls = [];
  state.repos.forEach(repo => {
    repo.pullRequests.forEach(pr => {
      allPulls.push({
        ...pr,
        repoId: repo.id,
        repoName: `${repo.owner || state.user.username}/${repo.name}`
      });
    });
  });

  // Sort by date descending
  allPulls.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

  const prRows = allPulls.map(pr => {
    const formattedDate = new Date(pr.createdAt).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric'
    });

    const isMerged = pr.status === 'merged';

    return `
      <div class="issue-row global-pr-item" data-repo-id="${pr.repoId}" data-pr-id="${pr.id}" style="cursor: pointer;">
        <div class="issue-icon ${isMerged ? 'closed' : 'open'}" style="color: ${isMerged ? 'var(--accent-purple)' : 'var(--accent-green)'};">
          <i data-lucide="git-pull-request" style="width: 16px; height: 16px;"></i>
        </div>

        <div class="issue-main">
          <div class="issue-title-line">
            <span class="issue-title" style="font-weight: 600; color: var(--text-primary);">${pr.title}</span>
            <span style="font-size: 0.75rem; color: var(--accent-blue); margin-left: 0.5rem;">${pr.repoName}</span>
          </div>
          <div class="issue-subinfo">
            #${pr.id} opened on ${formattedDate} by ${pr.author} &middot; <span style="text-transform: capitalize; color: ${isMerged ? 'var(--accent-purple)' : 'var(--accent-green)'}; font-weight: 600;">${pr.status}</span>
          </div>
        </div>

        <div class="issue-row-aside">
          ${pr.comments.length ? `
            <i data-lucide="message-square" style="width: 14px; height: 14px;"></i>
            <span>${pr.comments.length}</span>
          ` : ''}
        </div>
      </div>
    `;
  }).join('');

  return `
    <div class="content-wrapper" style="padding: 1.5rem 1rem; max-width: 1200px; margin: 0 auto;">
      <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 1.5rem;">
        <div style="font-weight: 700; font-size: 1.25rem; display: flex; align-items: center; gap: 0.5rem; color: var(--text-primary);">
          <i data-lucide="git-pull-request" style="color: var(--accent-blue);"></i>
          <span>Global Pull Requests</span>
        </div>
      </div>

      <div class="panel-container">
        <div class="panel-header" style="background: var(--bg-secondary); border-bottom: 1px solid var(--border-color); padding: 0.75rem 1rem;">
          <span style="font-size: 0.8125rem; font-weight: 600; color: var(--text-secondary);">
            ${allPulls.length} Total Pull Requests across all repositories
          </span>
        </div>

        <div class="issue-list">
          ${prRows || `
            <div class="empty-view-placeholder" style="padding: 4rem 2rem; text-align: center;">
              <i data-lucide="git-pull-request" style="width: 48px; height: 48px; color: var(--text-muted); margin-bottom: 1rem;"></i>
              <h3>No pull requests found</h3>
              <p style="color: var(--text-secondary); font-size: 0.875rem;">Create a pull request inside a repository to see it aggregated here!</p>
            </div>
          `}
        </div>
      </div>
    </div>
  `;
}

function renderPlaceholderModule(state) {
  const name = state.placeholderModuleName || 'Integration Module';
  return `
    <div class="content-wrapper" style="padding: 4rem 1rem; max-width: 800px; margin: 0 auto; text-align: center;">
      <div style="border: 1px solid var(--border-color); border-radius: 16px; padding: 4rem 2rem; background: var(--bg-card); box-shadow: var(--shadow-lg); backdrop-filter: var(--blur-backdrop); position: relative; overflow: hidden;">
        <div style="position: absolute; top: -50%; left: -50%; width: 200%; height: 200%; background: radial-gradient(circle, rgba(188, 140, 255, 0.08) 0%, transparent 60%); pointer-events: none; z-index: 1;"></div>

        <div style="position: relative; z-index: 2; display: flex; flex-direction: column; align-items: center; gap: 1.25rem;">
          <div style="width: 64px; height: 64px; border-radius: 50%; background: var(--accent-purple-bg); display: flex; align-items: center; justify-content: center; border: 1px solid rgba(188, 140, 255, 0.25);">
            <i data-lucide="sparkles" style="width: 28px; height: 28px; color: var(--accent-purple);"></i>
          </div>

          <h2 style="font-size: 1.5rem; font-weight: 700; color: var(--text-primary); margin: 0;">
            ${name} Workspace
          </h2>

          <p style="color: var(--text-secondary); font-size: 0.875rem; line-height: 1.6; max-width: 480px; margin: 0 auto;">
            The <strong>${name}</strong> component is fully scaffolded and styled. Connect this workspace to build triggers, notification sync servers, and AI deployment runtimes to go live.
          </p>

          <div style="display: flex; gap: 0.75rem; margin-top: 1rem;">
            <button class="btn btn-primary" onclick="window.location.reload();">
              <i data-lucide="refresh-cw" style="width: 14px; height: 14px;"></i>
              <span>Refresh Environment</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  `;
}

function attachGlobalIssuesListeners(state, actions) {
  const items = document.querySelectorAll(".global-issue-item");
  items.forEach(item => {
    item.addEventListener("click", () => {
      const repoId = item.getAttribute("data-repo-id");
      const issueId = item.getAttribute("data-issue-id");
      actions.navigateToRepoAndSelectIssue(repoId, issueId);
    });
  });
}

function attachGlobalPullsListeners(state, actions) {
  const items = document.querySelectorAll(".global-pr-item");
  items.forEach(item => {
    item.addEventListener("click", () => {
      const repoId = item.getAttribute("data-repo-id");
      const prId = item.getAttribute("data-pr-id");
      actions.navigateToRepoAndSelectPR(repoId, prId);
    });
  });
}

// INITIALIZE APP
document.addEventListener("DOMContentLoaded", () => {
  const app = new AppState();
  app.render();
});

